-- eAcharya Phase 6: NCERT-aligned Economics learning content for Classes 9-12 (alongside the existing Geography content).
-- Adds the Economics subject, six book courses (36 chapters), the syllabus (chapters) and official textbook links; lessons/videos are added by teachers,
-- and subject-neutral class descriptions. The forum is class-based (single general category), so no forum changes are needed.
-- No copyrighted textbook chapter text or PDF is copied into this migration. Geography content is not touched.
-- Back up production data before applying. The script is idempotent for subject, course, unit, lesson, content and resource rows.

-- 1. Subject-neutral class descriptions (the Phase 5 text described Geography only).
ON CONFLICT (grade) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;

-- 2. Economics subject.
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, is_active = true;

-- 3. One course per NCERT Economics book.
SELECT b.title, b.slug, b.description, cl.id, su.id, 'published'
FROM (VALUES
  (9, 'class-9-economics', 'Class 9 Economics', 'NCERT-aligned Class 9 Economics: village production, human resources, poverty and food security, with original study guides, chapter worksheets and an official textbook link.'),
  (10, 'class-10-understanding-economic-development', 'Class 10 Economics: Understanding Economic Development', 'NCERT-aligned Class 10 Economics covering development, sectors, money and credit, globalisation and consumer rights, with original notes and worksheets.'),
  (11, 'class-11-indian-economic-development', 'Class 11 Economics: Indian Economic Development', 'NCERT-aligned study of the Indian economy from the colonial period to present-day reforms, human capital, rural development, employment and sustainability, with original notes and worksheets.'),
  (11, 'class-11-statistics-for-economics', 'Class 11 Economics: Statistics for Economics', 'NCERT-aligned statistical tools for economics: collecting, organising and presenting data, averages, correlation and index numbers, with original notes and practice tasks.'),
  (12, 'class-12-introductory-microeconomics', 'Class 12 Economics: Introductory Microeconomics', 'NCERT-aligned microeconomics: scarcity and choice, consumer behaviour, production and costs, perfect competition and market equilibrium, with original notes and worksheets.'),
  (12, 'class-12-introductory-macroeconomics', 'Class 12 Economics: Introductory Macroeconomics', 'NCERT-aligned macroeconomics: national income, money and banking, income determination, the government budget and the open economy, with original notes and worksheets.')
) AS b(grade, slug, title, description)
JOIN public.classes cl ON cl.grade = b.grade
JOIN public.subjects su ON su.slug = 'economics'
ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, status = 'published';

-- 4. Temporary catalogue. Chapter names follow the current NCERT Economics books; confirm against the NCERT portal and the annual CBSE syllabus before formal use.
CREATE TEMP TABLE IF NOT EXISTS phase6_books (book_slug text PRIMARY KEY, grade smallint, title text, description text, official_url text, book_name text);
TRUNCATE TABLE phase6_books;
CREATE TEMP TABLE IF NOT EXISTS phase6_chapters (book_slug text, chapter_position integer, chapter_title text, focus text, activity text, question_one text, question_two text, objective_one text, objective_two text, PRIMARY KEY (book_slug, chapter_position));
TRUNCATE TABLE phase6_chapters;


-- 5. One unit per chapter. The unique constraint on (course_id, position) is deferrable, so update and insert are used instead of ON CONFLICT.
UPDATE public.units u SET title = 'Chapter ' || (ch.chapter_position + 1)::text || ': ' || ch.chapter_title, description = ch.focus
FROM phase6_chapters ch JOIN public.courses c ON c.slug = ch.book_slug
WHERE u.course_id = c.id AND u.position = ch.chapter_position;

SELECT c.id, 'Chapter ' || (ch.chapter_position + 1)::text || ': ' || ch.chapter_title, ch.focus, ch.chapter_position
FROM phase6_chapters ch JOIN public.courses c ON c.slug = ch.book_slug
WHERE NOT EXISTS (SELECT 1 FROM public.units u WHERE u.course_id = c.id AND u.position = ch.chapter_position);

-- 6. One official textbook reference per book. Idempotent by title within the course.
SELECT 'Official NCERT textbook: ' || b.book_name, 'Open the official NCERT textbook portal and choose this book. Check the current edition and the applicable annual syllabus.', 'link', c.id, 'NCERT textbook', b.official_url, true
FROM phase6_books b JOIN public.courses c ON c.slug = b.book_slug
WHERE NOT EXISTS (SELECT 1 FROM public.resources r WHERE r.course_id = c.id AND r.title = 'Official NCERT textbook: ' || b.book_name AND r.resource_type = 'link');

DROP TABLE phase6_chapters;
DROP TABLE phase6_books;
