INSERT INTO public.courses (title, slug, description, class_id, subject_id, status)
INSERT INTO phase6_books (book_slug, grade, title, description, official_url, book_name) VALUES
  ('class-9-economics', 9, 'Class 9 Economics', 'NCERT-aligned Class 9 Economics: village production, human resources, poverty and food security, with original study guides, chapter worksheets and an official textbook link.', 'https://ncert.nic.in/textbook.php', 'Economics'),
  ('class-10-understanding-economic-development', 10, 'Class 10 Economics: Understanding Economic Development', 'NCERT-aligned Class 10 Economics covering development, sectors, money and credit, globalisation and consumer rights, with original notes and worksheets.', 'https://ncert.nic.in/textbook.php', 'Understanding Economic Development'),
  ('class-11-indian-economic-development', 11, 'Class 11 Economics: Indian Economic Development', 'NCERT-aligned study of the Indian economy from the colonial period to present-day reforms, human capital, rural development, employment and sustainability, with original notes and worksheets.', 'https://ncert.nic.in/textbook.php', 'Indian Economic Development'),
  ('class-11-statistics-for-economics', 11, 'Class 11 Economics: Statistics for Economics', 'NCERT-aligned statistical tools for economics: collecting, organising and presenting data, averages, correlation and index numbers, with original notes and practice tasks.', 'https://ncert.nic.in/textbook.php', 'Statistics for Economics'),
  ('class-12-introductory-microeconomics', 12, 'Class 12 Economics: Introductory Microeconomics', 'NCERT-aligned microeconomics: scarcity and choice, consumer behaviour, production and costs, perfect competition and market equilibrium, with original notes and worksheets.', 'https://ncert.nic.in/textbook.php', 'Introductory Microeconomics'),
  ('class-12-introductory-macroeconomics', 12, 'Class 12 Economics: Introductory Macroeconomics', 'NCERT-aligned macroeconomics: national income, money and banking, income determination, the government budget and the open economy, with original notes and worksheets.', 'https://ncert.nic.in/textbook.php', 'Introductory Macroeconomics');
INSERT INTO phase6_chapters (book_slug, chapter_position, chapter_title, focus, activity, question_one, question_two, objective_one, objective_two) VALUES
  ('class-9-economics', 0, 'The Story of Village Palampur', 'Production in a village combines land, labour, physical capital and human capital. Land is fixed, so farmers raise output through multiple cropping, modern methods and irrigation, and these choices carry costs for soil and groundwater. Non-farm activities such as dairy, small manufacturing and shops add to incomes where farm work is limited.', 'Draw a simple chart of the four factors of production for a farm or small shop in your area and list one way each could be used more sustainably.', 'Why is land considered a fixed factor, and how can farmers still increase production from the same land?', 'How can non-farm activities help a village where farm work is seasonal?', 'Name and explain the factors of production using a village example.', 'Compare ways of increasing farm output with their environmental costs.'),
  ('class-9-economics', 1, 'People as Resource', 'People become a resource when education, training and health improve their productivity; this is often called human capital formation. Economic activities are grouped into primary, secondary and tertiary sectors, and unemployment can be seasonal, disguised or educated. The quality of a population depends on literacy, health and skills, not only on its size.', 'Prepare a small table showing the economic activities and skill needs of five occupations around you.', 'How does investment in education and health turn a population into a human resource?', 'Explain disguised unemployment with a farm-household example.', 'Distinguish population as a liability from population as human capital.', 'Classify activities as economic or non-economic and by sector.'),
  ('class-9-economics', 2, 'Poverty as a Challenge', 'Poverty is multidimensional: it includes low income and consumption, but also poor access to health, education, housing and security. The poverty line is a benchmark built on minimum consumption needs, so estimates depend on the method and the year used. Causes include low growth, unequal assets and limited jobs, and responses include employment programmes, food support and investment in basic services.', 'Compare two households using income, food, schooling and health access, and note what a single poverty-line number might leave out.', 'Why is poverty described as more than a lack of income?', 'Why do poverty estimates depend on the method and the year used?', 'Explain the poverty line and vulnerability with examples.', 'Evaluate anti-poverty approaches by what they actually change for households.'),
  ('class-9-economics', 3, 'Food Security in India', 'Food security means that food is available, accessible and affordable for everyone at all times. Availability depends on production and stocks, access on income and distribution, and affordability on prices. India uses buffer stocks, minimum support prices and the public distribution system, though leakages and uneven access remain challenges; cooperatives and community efforts also help.', 'Trace how a kilogram of wheat or rice might move from farm to a ration shop, marking where availability, access or affordability could break down.', 'What are the three dimensions of food security?', 'How do buffer stocks and the public distribution system support food security?', 'Explain availability, accessibility and affordability of food.', 'Describe how public policy tries to protect people from hunger.'),
  ('class-10-understanding-economic-development', 0, 'Development', 'Development means improvement in the conditions people value, so goals differ between people and can even conflict. Income is one indicator, but averages hide inequality, so indicators such as literacy, life expectancy, health and per-capita income are used together. Development must also be sustainable: resources should be used so that future generations are not left worse off.', 'Compare two states or countries on per-capita income, literacy and infant mortality from an official source, and say which indicator tells you most; note the data year.', 'Why can different people have different development goals?', 'Why is average income not enough to judge development?', 'Explain development goals and the limits of averages.', 'Link human development indicators to sustainability.'),
  ('class-10-understanding-economic-development', 1, 'Sectors of the Indian Economy', 'Economic activities are grouped into primary, secondary and tertiary sectors, and an economy’s structure changes as the shares of output and employment shift. GDP measures the value of final goods and services produced, which avoids double counting of intermediate goods. Employment can stay concentrated in a sector whose share of output has fallen, leading to underemployment; organised and unorganised, and public and private, are other useful divisions.', 'Draw a flow chart for a product such as bread or cloth and mark which steps belong to the primary, secondary and tertiary sectors.', 'Why are only final goods counted in GDP?', 'What does it mean when most workers are in a sector that produces a small share of GDP?', 'Classify activities by sector and by organisation.', 'Interpret changes in output and employment shares.'),
  ('class-10-understanding-economic-development', 2, 'Money and Credit', 'Money works as a medium of exchange and removes the need for a double coincidence of wants. Modern money includes currency and bank deposits, and banks lend part of their deposits, creating credit. Credit has terms such as interest rate, collateral, documents and repayment period, and it can raise incomes or trap borrowers in debt depending on circumstances. Formal sources are regulated, whereas informal lenders often charge more; self-help groups offer another route.', 'List the credit sources available to a farmer and to a small shopkeeper and compare them on interest, collateral and flexibility.', 'How does money overcome the double coincidence of wants?', 'Why can the same loan help one borrower and harm another?', 'Explain the role of banks and the terms of credit.', 'Compare formal and informal sources of credit.'),
  ('class-10-understanding-economic-development', 3, 'Globalisation and the Indian Economy', 'Globalisation is the growing integration of markets through trade, investment and technology. Multinational companies spread production across countries, and liberalisation reduced barriers to trade and investment. Consumers may gain choice and lower prices, while small producers can struggle to compete; fair rules and attention to labour and the environment shape who benefits.', 'Choose a product on your desk and trace where its design, parts, assembly and sale might occur; mark one gain and one risk for workers in India.', 'How do multinational companies link production across countries?', 'Why might small producers be affected differently from large firms?', 'Describe the factors that enabled globalisation.', 'Assess gains and risks for producers, workers and consumers.'),
  ('class-10-understanding-economic-development', 4, 'Consumer Rights', 'Markets can be unfair when information is limited, so consumers may be misled on quality, price or safety. Consumer rights include safety, information, choice and redress, and laws and consumer courts provide ways to seek a remedy. Awareness, bills, standardisation marks and organised consumer groups strengthen the buyer’s position.', 'Collect two packaged products and note the label details (price, dates, standards mark) that help a buyer make an informed choice.', 'Why do buyers need protection when sellers know more about a product?', 'How can consumer courts and standardisation marks help?', 'List consumer rights and the duties that go with them.', 'Explain how consumers can seek redress.'),
  ('class-11-indian-economic-development', 0, 'Indian Economy on the Eve of Independence', 'Under colonial rule the economy stagnated, with heavy dependence on agriculture, a weak industrial base and policy that served British interests. Trade patterns made India an exporter of raw materials and an importer of manufactured goods, and a drain of resources and poor infrastructure limited development. Literacy and life expectancy were low. Railways and administrative changes brought some benefits but mainly served colonial aims.', 'Make a timeline of three colonial-era policies and mark one effect of each on agriculture, industry or trade.', 'How did colonial trade policy shape the structure of India’s economy?', 'Why was industrial growth limited at independence?', 'Describe the main features of the colonial economy.', 'Evaluate the economic effects of colonial policy using evidence.'),
  ('class-11-indian-economic-development', 1, 'Indian Economy 1950–1990', 'Independent India chose a mixed economy with central planning and a large public sector. Five Year Plans set goals of growth, modernisation, self-reliance and equity, supported by land reforms, the Green Revolution and industrial licensing. Import substitution and controls protected domestic producers but limited efficiency and competition. Judging the period means comparing achievements with the constraints faced.', 'Make a two-column table of the strengths and weaknesses of import substitution and industrial licensing.', 'Why did India adopt a mixed economy and planning after independence?', 'What were the gains and limits of the Green Revolution?', 'Explain planning goals and the role of the public sector.', 'Assess policy choices with evidence from agriculture and industry.'),
  ('class-11-indian-economic-development', 2, 'Liberalisation, Privatisation and Globalisation: An Appraisal', 'The 1991 balance of payments crisis led to reforms in industrial licensing, trade, finance and the role of the public sector. Liberalisation reduced controls, privatisation shifted ownership of some enterprises, and globalisation tied India more closely to world markets. Services and overall growth expanded, yet concerns remain about uneven outcomes in agriculture, employment and regions. An appraisal weighs benefits and costs with data.', 'Compare growth, inflation and sector shares before and after 1991 using an official source; state the years and units.', 'What triggered the 1991 reforms?', 'Which groups gained and which faced difficulties after the reforms?', 'Define liberalisation, privatisation and globalisation.', 'Evaluate the reforms using sector-wise evidence.'),
  ('class-11-indian-economic-development', 3, 'Human Capital Formation in India', 'Human capital is the stock of skill, knowledge and health embodied in people, built through education, health care, on-the-job training, migration and information. Spending on these raises productivity and wellbeing, but returns depend on quality and access. Differences by gender, region and income show why public policy matters. Human capital is related to, but not the same as, human development.', 'Compare public spending on education and on health using a small table from an official source and describe one gap.', 'How does investment in education and health raise productivity?', 'Why do gender and regional gaps in access matter?', 'Explain the sources of human capital formation.', 'Relate human capital to growth and human development.'),
  ('class-11-indian-economic-development', 4, 'Rural Development', 'Rural development covers credit, marketing, diversification of activities, employment and infrastructure. Cooperative and formal credit can reduce reliance on moneylenders, while better marketing improves the prices farmers receive. Diversification into animal husbandry, fisheries and non-farm work reduces dependence on crops, and practices such as organic farming add new options. Success depends on access, skills and finance.', 'Map the credit, storage and market options available to farmers near you and identify one missing link.', 'Why is access to formal credit important for farmers?', 'How does diversification reduce rural risk?', 'Describe credit and marketing institutions in rural areas.', 'Evaluate diversification and organic farming as strategies.'),
  ('class-11-indian-economic-development', 5, 'Employment: Growth, Informalisation and Other Issues', 'Workers are classified as self-employed, regular salaried or casual labour, and their work as formal or informal. Participation rates, unemployment and the movement of workers across sectors describe the labour market. Growth does not always generate jobs, and informalisation raises concerns about security and working conditions. Policy responses include skill programmes and employment guarantees.', 'Interview an adult about their work, classify it by type and sector, and note whether it is formal or informal.', 'What is the difference between formal and informal employment?', 'Why might growth not create enough good jobs?', 'Interpret the worker-population ratio and employment categories.', 'Discuss causes of informalisation and policy responses.'),
  ('class-11-indian-economic-development', 6, 'Environment and Sustainable Development', 'The environment supplies resources, absorbs waste, supports life and adds to wellbeing, but its capacity to absorb waste is limited. Global warming, ozone depletion and land degradation show that growth can impose environmental costs. Sustainable development meets present needs without reducing the options of future generations, using cleaner energy, efficient resource use and traditional knowledge. Trade-offs are real, so evidence and local context matter.', 'List the functions the environment performs for your locality and one threat to each.', 'What are the main functions of the environment?', 'Why is sustainable development a matter of trade-offs rather than a free choice?', 'Explain environmental functions and the idea of absorptive capacity.', 'Evaluate strategies for sustainable development.'),
  ('class-11-indian-economic-development', 7, 'Comparative Development Experiences of India and its Neighbours', 'Comparing India with neighbouring countries uses indicators such as GDP growth, sector shares, demographic features and human development. Neighbours followed different paths and institutions, which shaped how fast they grew and what they achieved in health and education. Comparisons must use the same years and definitions, and each country’s starting point matters. The aim is to learn from differences instead of ranking countries by a single number.', 'Make a small comparison table of India and two neighbours on population, growth and one human development indicator, citing the year and source.', 'Why must comparisons across countries use the same year and definition?', 'How can different development strategies lead to different results?', 'Compare countries using growth and human development indicators.', 'Explain why initial conditions and policy choices matter.'),
  ('class-11-statistics-for-economics', 0, 'Introduction', 'Statistics in economics means both numerical data and the methods used to collect, organise, present and interpret them. Economists use statistics to describe patterns, test claims and support policy decisions. Data can mislead if collection is biased or if a graph or an average is chosen poorly, so stating limitations is part of good practice.', 'Find one statistic in a news report and note what was measured, for whom, in which year and by whom.', 'What are the two senses in which the word statistics is used?', 'How can statistics be misused?', 'Explain the scope and importance of statistics in economics.', 'Identify the limits of statistical evidence.'),
  ('class-11-statistics-for-economics', 1, 'Collection of Data', 'Data can come from primary sources collected directly or secondary sources collected by others. A census and a sample survey differ in coverage, cost and accuracy, and sampling can be random or non-random. Errors arise from sampling, measurement and non-response, and official sources should be cited with their year.', 'Design a five-question survey for classmates, decide your sample, and list two ways bias could creep in.', 'When is a sample survey preferable to a census?', 'What is the difference between sampling and non-sampling error?', 'Distinguish primary and secondary data.', 'Describe sampling methods and sources of error.'),
  ('class-11-statistics-for-economics', 2, 'Organisation of Data', 'Raw data are organised through classification into groups, frequency distributions and tabulation. Variables are discrete or continuous, and class intervals can be exclusive or inclusive. A well-built frequency table shows patterns that raw numbers hide, and its classes, headings and units should be clear.', 'Collect the heights or marks of 30 classmates, build a frequency table with suitable class intervals and describe the pattern.', 'What is the difference between a discrete and a continuous variable?', 'Why are class intervals chosen carefully?', 'Construct a frequency distribution from raw data.', 'Classify variables and data.'),
  ('class-11-statistics-for-economics', 3, 'Presentation of Data', 'Data can be presented through tables, diagrams and graphs such as bar diagrams, pie charts, histograms, frequency polygons and ogives. The best form depends on the kind of variable and the message, and clear titles, scales and labels keep a presentation honest. Distorted axes can create wrong impressions.', 'Draw a histogram and a bar diagram for suitable data and describe what each shows better.', 'How do a histogram and a bar diagram differ?', 'How can a truncated axis mislead readers?', 'Choose and draw a suitable chart for given data.', 'Read and interpret graphs critically.'),
  ('class-11-statistics-for-economics', 4, 'Measures of Central Tendency', 'Mean, median and mode summarise a distribution with a single representative value. The mean uses all values but is sensitive to extremes, the median is the middle value and is more stable with outliers, and the mode is the most frequent value. Which measure suits a situation depends on the data and the purpose.', 'Compute the three measures for a small data set, add one extreme value and observe which measure changes most.', 'Why can the median be a better summary than the mean for incomes?', 'When is the mode the most useful measure?', 'Calculate mean, median and mode for different kinds of data.', 'Choose an appropriate average and justify the choice.'),
  ('class-11-statistics-for-economics', 5, 'Correlation', 'Correlation describes the strength and direction of a linear relationship between two variables, shown by a scatter diagram and measured by a coefficient between −1 and +1. A positive value means the variables move together, a negative value means they move in opposite directions, and a value near zero means little linear relation. Correlation does not prove causation.', 'Plot study hours against marks for ten students, or a similar pair of variables, and describe the relationship in words.', 'What does a correlation coefficient near zero tell us?', 'Why does correlation not prove causation?', 'Interpret scatter diagrams and correlation coefficients.', 'Calculate a correlation coefficient for a small data set.'),
  ('class-11-statistics-for-economics', 6, 'Index Numbers', 'An index number measures the average change in a group of related variables over time relative to a base period. Price indices such as the consumer price index track the cost of a fixed basket, and weights show how important each item is. The choice of base year, basket and weights affects the result, and indices are used to adjust wages and to measure inflation.', 'Build a price index for a basket of four items using prices from two periods and compute the percentage change.', 'Why do price indices use weights?', 'How can a change of base year change an index?', 'Construct a weighted price index.', 'Use an index to calculate inflation and real change.'),
  ('class-11-statistics-for-economics', 7, 'Use of Statistics', 'Statistical tools support real decisions: spreadsheets and simple software help organise and graph data, while careful reading checks the source, the sample and the measure. This chapter brings earlier tools together to answer a question from data, from framing the question to stating a limited conclusion. Good practice reports the method, the uncertainty and what the data cannot show.', 'Choose a question about your school or locality, collect a small data set, apply two statistical tools and write a three-sentence conclusion with one limitation.', 'What steps take a question from data collection to a conclusion?', 'Why should a report state its limitations?', 'Apply tools from earlier chapters to a small project.', 'Communicate findings with method and limits.'),
  ('class-12-introductory-microeconomics', 0, 'Introduction', 'Microeconomics studies how individual consumers, producers and markets make choices when resources are scarce. Scarcity forces choice, and every choice has an opportunity cost, which a production possibilities frontier makes visible. Every economy must decide what to produce, how to produce and for whom, and answers its central problems through markets, planning or a mix of both.', 'Draw a production possibilities frontier for two goods and show how better technology shifts it.', 'What is opportunity cost, and how does a production possibilities frontier show it?', 'Why does every economy face the same central problems?', 'Explain scarcity, choice and opportunity cost.', 'Interpret movements along and shifts of a production possibilities frontier.'),
  ('class-12-introductory-microeconomics', 1, 'Theory of Consumer Behaviour', 'A consumer chooses the bundle that gives the most satisfaction within income and prices; the budget set shows what is affordable. Utility and indifference curves describe preferences, and diminishing marginal utility explains why extra units add less satisfaction. The law of demand links price and quantity inversely: a price change moves us along the demand curve, whereas changes in income, related prices or tastes shift it, and price elasticity measures how strongly quantity responds.', 'Draw a budget line for two goods with a given income and prices, then show what happens when one price falls.', 'How does a price change move the budget line?', 'What is the difference between a movement along and a shift of the demand curve?', 'Explain consumer equilibrium using utility or indifference curves.', 'Derive and interpret the demand curve and its determinants.'),
  ('class-12-introductory-microeconomics', 2, 'Production and Costs', 'Production turns inputs into output. In the short run at least one factor is fixed, so returns to the variable factor eventually diminish; total, average and marginal product are related to each other. Costs split into fixed and variable, with average and marginal cost curves of characteristic shape. In the long run all inputs are variable and returns to scale apply. Costs guide what a firm can supply profitably.', 'Build a table of output with total, average and marginal cost for a small firm and plot the average and marginal cost curves.', 'Why does the marginal cost curve cut the average cost curve at its minimum?', 'What is the difference between the short run and the long run?', 'Relate total, average and marginal product and cost.', 'Distinguish diminishing returns from returns to scale.'),
  ('class-12-introductory-microeconomics', 3, 'The Theory of the Firm under Perfect Competition', 'In perfect competition many buyers and sellers trade a homogeneous product at a price none of them can influence, and entry and exit are free. A profit-maximising firm produces where price equals marginal cost with marginal cost rising, so its supply curve is the rising part of marginal cost above minimum average variable cost. Supply shifts with input prices, technology and taxes, and elasticity of supply measures responsiveness.', 'Using a cost table and a given market price, find the profit-maximising output and the total profit or loss.', 'Why does a price-taking firm produce where price equals marginal cost?', 'What shifts a firm’s supply curve?', 'State the features of perfect competition.', 'Derive the firm’s supply curve and find profit-maximising output.'),
  ('class-12-introductory-microeconomics', 4, 'Market Equilibrium', 'Equilibrium occurs where market demand equals market supply and the price clears the market. Excess demand pushes the price up and excess supply pushes it down, and shifts of demand or supply change the equilibrium price and quantity. Price ceilings and floors can cause shortages or surpluses, and free entry and exit bring profits back to normal in the long run. Separate a shift from a movement before predicting the new equilibrium.', 'Draw demand and supply, shift one of them for a real event such as a bumper harvest, and read off the new price and quantity.', 'How does the market reach equilibrium from a position of excess demand?', 'What happens when a price ceiling is set below the equilibrium price?', 'Determine equilibrium price and quantity graphically and numerically.', 'Analyse the effects of shifts and price controls.'),
  ('class-12-introductory-macroeconomics', 0, 'Introduction', 'Macroeconomics studies the economy as a whole: output, employment, prices and the external sector. It focuses on aggregates and on the interaction of households, firms, government and the rest of the world. The circular flow of income shows how spending, production and income connect, and stock and flow variables must be told apart. Questions about growth, inflation and jobs belong here.', 'Draw a circular flow of income with households, firms, government and the foreign sector and label two flows in each direction.', 'Why is macroeconomics more than the sum of individual markets?', 'What is the difference between stock and flow variables?', 'Explain the scope of macroeconomics and the circular flow.', 'Distinguish stocks and flows with examples.'),
  ('class-12-introductory-macroeconomics', 1, 'National Income Accounting', 'National income measures the value of final goods and services produced in a year by three methods, product, income and expenditure, which give the same total in principle. GDP, GNP, net product and real versus nominal values differ in coverage and in price adjustment. Per-capita figures and deflators help comparisons, though GDP leaves out unpaid work and environmental damage.', 'Take a small set of final and intermediate transactions, find the value added at each stage and add up to GDP.', 'Why does GDP exclude intermediate goods?', 'Why does real GDP give a better picture of growth than nominal GDP?', 'Calculate national income by the three methods.', 'Distinguish GDP, GNP, nominal and real measures and note their limits.'),
  ('class-12-introductory-macroeconomics', 2, 'Money and Banking', 'Money serves as a medium of exchange, unit of account, store of value and standard of deferred payment. Commercial banks accept deposits and create credit, and the money multiplier links reserves to the money supply. The central bank influences money and credit through policy tools such as the reserve requirement and the policy interest rate. Understanding these links explains how credit and prices respond.', 'Work out a simple money-creation example with a reserve ratio of 20 per cent over three rounds of deposits and loans.', 'How do banks create credit from deposits?', 'How can a central bank change the money supply?', 'Explain the functions of money and of banks.', 'Describe how the central bank uses policy tools.'),
  ('class-12-introductory-macroeconomics', 3, 'Determination of Income and Employment', 'In the simple Keynesian model, output is determined by aggregate demand when prices are fixed and resources are underemployed. Consumption depends on income, saving is the remainder, and equilibrium output is where planned aggregate demand equals output. The multiplier shows that a change in autonomous spending changes income by a larger amount, and gaps between demand and full-employment output can be inflationary or deflationary.', 'Using a given consumption function and level of investment, find equilibrium income and the effect of a rise in investment through the multiplier.', 'How is equilibrium income determined in the simple model?', 'Why is the multiplier larger when the marginal propensity to consume is higher?', 'Derive equilibrium output using aggregate demand and supply.', 'Apply the multiplier and describe demand gaps.'),
  ('class-12-introductory-macroeconomics', 4, 'Government Budget and the Economy', 'The government budget records expected receipts and spending and serves allocation, distribution and stabilisation. Revenue and capital receipts, revenue and capital expenditure, and the revenue, fiscal and primary deficits show how spending is financed. Borrowing adds to debt and affects future budgets, so the kind of deficit matters more than a single headline figure.', 'From a simple made-up budget, calculate the revenue, fiscal and primary deficits and describe what each reveals.', 'How is the fiscal deficit different from the revenue deficit?', 'How can taxes and spending be used to stabilise the economy?', 'Classify budget receipts and expenditure.', 'Calculate and interpret different deficit measures.'),
  ('class-12-introductory-macroeconomics', 5, 'Open Economy Macroeconomics', 'Open economies trade goods and assets with the rest of the world, recorded in the balance of payments through a current account and a capital account. The exchange rate, the price of one currency in terms of another, may be fixed, flexible or managed, and changes in it alter relative prices and trade. A current account deficit must be financed by capital inflows or reserves, and the choice of exchange-rate system involves trade-offs.', 'Use a simple exchange-rate example to show how depreciation changes the rupee price of an imported item and the foreign price of an export.', 'What does the current account record?', 'How does depreciation of a currency affect exports and imports?', 'Explain the structure of the balance of payments.', 'Analyse exchange-rate systems and their effects.');
